package com.bibliotech.book.controller;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(NoSuchElementException.class)ResponseEntity<String> n(NoSuchElementException e){return ResponseEntity.status(404).body(e.getMessage());}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<String>b(IllegalArgumentException e){return ResponseEntity.badRequest().body(e.getMessage());}}
